<script setup lang="ts">import {ref,onMounted,computed,watch} from 'vue';import {useRoute} from 'vue-router';import {useResearch} from '../stores/research';import {useAuth} from '../stores/auth';import {createPlan,approvePlan,downloadPlan} from '../api/plans';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';const route=useRoute(),lab=useResearch(),auth=useAuth(),data=ref({title:'条件差异的独立复烧验证',run_id:Number(route.query.run)||0,contrast_index:1,action:'重新随机分配独立试片，复核当前温度与釉层条件差异，并记录窑位及配料批次。',verification:'独立批次复烧，先核对残差、同方差与实验执行；不将单项显著差异直接作为量产结论。'}),{busy,error,perform}=useTask();const run=computed(()=>lab.runs.find(r=>r.id===data.value.run_id));onMounted(()=>perform(async()=>{await lab.load();if(!data.value.run_id)data.value.run_id=lab.runs.find(r=>r.status==='completed')?.id||0;}));watch(()=>data.value.run_id,()=>{data.value.contrast_index=1;});function submit(){perform(async()=>{await createPlan(data.value);await lab.load();data.value.title='';});}function approve(id:number){perform(async()=>{await approvePlan(id);await lab.load();});}</script><template><PageHeading index="05" title="把统计线索，变成下一次独立实验" text="分析员写明条件与验证计划，负责人审批后交付完整ANOVA和全部预设对比。"/><ErrorNotice :message="error" @retry="perform(lab.load)"/><div class="plan-layout" :class="{readonly:!auth.canEdit}"><form v-if="auth.canEdit" class="research-form" @submit.prevent="submit"><h2>后续实验提案</h2><label>提案标题<input v-model="data.title" required minlength="2"></label><label>依据分析<select v-model="data.run_id"><option v-for="r in lab.runs.filter(r=>r.status==='completed')" :key="r.id" :value="r.id">#{{r.id}} {{r.name}}</option></select></label><label>关注的预设对比<select v-model="data.contrast_index"><option v-for="c in run?.result.contrasts" :key="c.index" :value="c.index">#{{c.index}} {{c.condition_factor}}={{c.condition}} / {{c.left}}−{{c.right}}</option></select></label><label>后续实验行动<textarea v-model="data.action" rows="5" required minlength="10"></textarea></label><label>独立验证与解释限制<textarea v-model="data.verification" rows="5" required minlength="10"></textarea></label><button class="primary" :disabled="busy||!run">保存待审批提案 →</button></form><section class="plan-files"><article v-for="p in lab.plans" :key="p.id"><div class="file-heading"><p class="eyebrow">FOLLOWUP EXPERIMENT / {{String(p.id).padStart(3,'0')}}</p><StatusBadge :status="p.status"/></div><h2>{{p.title}}</h2><p class="plan-reference">依据分析 #{{p.run_id}} / 关注对比 #{{p.contrast_index}} <small>交付保留全部对比，不只导出所选一项。</small></p><h3>行动</h3><p>{{p.action}}</p><h3>验证与限制</h3><p>{{p.verification}}</p><footer><template v-if="p.status==='draft'"><button v-if="auth.user?.role==='admin'" class="outline" :disabled="busy" @click="approve(p.id)">审批并批准交付 ✓</button><small>等待实验负责人审批</small></template><template v-else><small>批准人 {{p.approved_by}}</small><button class="text-button" :disabled="busy" @click="perform(()=>downloadPlan(p.id))">下载完整实验CSV ↓</button></template></footer></article></section></div></template>
